scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV2_AWS_51'] || []

control 'CKV2_AWS_51' do
  title 'Ensure AWS API Gateway endpoints uses client certificate authentication'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_api_gateway_stage resources that actually exist, enumerated
    through the two-step (parent -> child) declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    A client certificate is how the backend proves a request actually came
    through API Gateway. Without one, anything that learns the backend URL
    can call it directly and bypass the gateway's authorizers and
    throttling.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Ensure AWS API Gateway endpoints uses client
    certificate authentication
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_api_gateway_stage:

      resource "aws_api_gateway_client_certificate" "example" {
        description = "backend mTLS"
      }

      resource "aws_api_gateway_stage" "example" {
        rest_api_id           = aws_api_gateway_rest_api.example.id
        deployment_id         = aws_api_gateway_deployment.example.id
        stage_name            = "prod"
        client_certificate_id = aws_api_gateway_client_certificate.example.id
      }

    Out of band — aws_api_gateway_stage:

      aws apigateway update-stage --rest-api-id <api-id> --stage-name prod --patch-operations op=replace,path=/clientCertificateId,value=<client-cert-id>

    Terraform — aws_apigatewayv2_stage:

      resource "aws_apigatewayv2_stage" "example" {
        api_id                = aws_apigatewayv2_api.example.id
        name                  = "prod"
        client_certificate_id = aws_api_gateway_client_certificate.example.id
      }

    Out of band — aws_apigatewayv2_stage:

      aws apigatewayv2 update-stage --api-id <api-id> --stage-name prod --client-certificate-id <client-cert-id>
  FIX

  tag checkov_id:            'CKV2_AWS_51'
  tag checkov_category:      'GENERAL_SECURITY'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'graph'
  tag tf_resources:          %w[aws_api_gateway_stage aws_apigatewayv2_api aws_apigatewayv2_stage]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/api_gateway_stage'
  tag nist:                  ['IA-3', 'SC-8', 'AC-3']
  tag nist_r4:               ['IA-3', 'SC-8', 'AC-3']
  tag cci:                   ['CCI-000778', 'CCI-002418']
  tag ksi:                   ['KSI-IAM-CTL']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_api_gateway_stage', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
  # one with nothing in it. A missing SDK gem, a denied call or an unreachable
  # endpoint all end up here, and without this assertion they render as "no
  # assets" and the control reports Not Applicable: the worst case reported as
  # "does not apply here".
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe "aws_api_gateway_stage enumeration" do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # A child list call that failed took a whole SUBTREE with it. That is not
  # "this parent had nothing", and it must never render as one: it is reported
  # per parent here, and it keeps the control APPLICABLE below so that only_if
  # cannot turn a broken enumeration into "does not apply here".
  parent_failures = assets.parent_failures
  unless parent_failures.empty?
    describe "aws_api_gateway_stage enumeration" do
      it 'read the children of every parent it enumerated' do
        expect(parent_failures.map { |f| "#{f[:region]}/#{f[:parent_id]}: #{f[:error]}" }).to be_empty
      end
    end
  end

  # A blank id means the spec's `id` column names a member this response does
  # not carry. tools/lint_resource_map.py cannot see that statically, and the
  # damage is silent: every describe is titled with a blank where the identity
  # belongs, and `exempt_assets` entries keyed by id stop matching. Asserted,
  # not filtered — filtering renders Not Applicable, which is the same silence.
  enumerated = assets.assets(exempt: exempt)
  unusable = enumerated.count { |a| "#{a[:id]}".strip.empty? }
  if unusable.positive?
    describe "aws_api_gateway_stage enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `id` for aws_api_gateway_stage in "\
          'tools/api_specs.yml likely names a member this API does not return'
      end
    end
  end

  # A nil field is the FAILING state for a presence check, so it is
  # deliberately not filtered out here.
  in_scope = enumerated

  # `applicable` is a CLAIM that this rule does not apply to this boundary, and
  # only an enumeration that succeeded can earn it. An unreadable region or a
  # blank id column keeps the control applicable so the assertions above are
  # reported; without that, only_if skips the whole control — the two guards
  # included — and the worst case, "every region denied", renders as Not
  # Applicable. The stock template already carries the `unusable` half of this.
  applicable = !in_scope.empty? || !unreadable.empty? || unusable.positive? || !parent_failures.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if("no aws_api_gateway_stage in scope expressing this setting "\
          "(#{assets.parents_seen} parent(s) enumerated by get_rest_apis)") { applicable }

  in_scope.each do |asset|
    describe "aws_api_gateway_stage #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:client_certificate_id] }
      it { should satisfy('be set') { |v| !v.nil? && !(v.respond_to?(:empty?) && v.empty?) } }
    end
  end
end
